#requires -version 5.1
<##
    PC•REPORT — Windows / Remote
    Локальный сборщик Windows и SSH-клиент для Windows/Linux.
##>

param(
    [Alias('help')]
    [switch]$h,
    [Alias('remote')]
    [string]$r,

    # PS1 signing / trust management (integrated from Signer.ps1)
    [Parameter(Position = 0)]
    [Alias('f', 'file', 'folder', 'path')]
    [string]$Target,
    [switch]$Init,
    [switch]$NewCert,
    [switch]$SetPolicy,
    [ValidateSet('RemoteSigned', 'AllSigned', 'Bypass', 'Restricted')]
    [string]$ExecutionPolicy = 'RemoteSigned',
    [switch]$PolicyAllSigned,
    [string]$CertName = 'Local PowerShell Code Signing',
    [ValidateRange(1, 30)]
    [int]$Years = 5,
    [switch]$NoRecurse,
    [switch]$Unblock,
    [switch]$VerifyOnly,
    [switch]$NoTrust,
    [switch]$SignerHelp,
    [switch]$RemoteExportBase64
)

$ErrorActionPreference = 'Stop'
[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
# Отсутствующие свойства оборудования допустимы; ошибки операций обрабатываются явно.
$ScriptDir = if ($PSScriptRoot) { $PSScriptRoot } else {
    $exe = [Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
    if ([IO.Path]::GetExtension($exe) -eq '.exe' -and [IO.Path]::GetFileName($exe) -notmatch '^(powershell|pwsh)\.exe$') { [IO.Path]::GetDirectoryName($exe) }
    else { (Get-Location).Path }
}
$ReportDate = Get-Date
function Write-Log([string]$Message) {
    # SSH может менять кодовую страницу общей консоли; обновляем и её, и writer .NET.
    [Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
    [Console]::Error.WriteLine(('[{0}] {1}' -f (Get-Date -Format 'HH:mm:ss'), $Message))
}
# PAYLOADS_BEGIN
$EmbeddedLinux = ''
$EmbeddedWindows = ''
# PAYLOADS_END
function Save-Report([string]$ComputerName, [byte[]]$Bytes) {
    if ($Bytes.Length -eq 0) { throw 'Отчёт пуст.' }
    $text = [Text.Encoding]::UTF8.GetString($Bytes)
    if ($text -notmatch '(?is)^\s*<!DOCTYPE html>.*</html>\s*$') { throw 'Получен некорректный HTML-отчёт.' }
    $safe = $ComputerName -replace '[^\p{L}\p{N}._-]', '_'
    if (-not $safe) { $safe = 'computer' }
    $out = Join-Path $ScriptDir ('PC_Report_{0}_{1}_{2}.html' -f $safe,(Get-Date -Format 'yyyyMMdd_HHmmss'),[Guid]::NewGuid().ToString('N').Substring(0,8))
    $tmp = "$out.tmp"
    try { [IO.File]::WriteAllBytes($tmp,$Bytes); [IO.File]::Move($tmp,$out) }
    finally { if ([IO.File]::Exists($tmp)) { [IO.File]::Delete($tmp) } }
    Write-Log "Отчёт сохранён: $out"
}

function Show-Help {
@'
PC•REPORT — Windows / SSH Remote

НАЗНАЧЕНИЕ
  Сбор полной конфигурации ПК и создание автономного HTML-отчёта.
  Скрипт pc-report.ps1 запускается на Windows. В remote-режиме он
  автоматически определяет ОС удалённого хоста и использует:
    Windows → pc-report.ps1
    Linux   → pc-report.sh

ИСПОЛЬЗОВАНИЕ
  .\pc-report.ps1
      Локальный отчёт Windows.

  .\pc-report.ps1 -h
      Полная справка.

  .\pc-report.ps1 -r user@host
      SSH-отчёт одного удалённого ПК. Порт по умолчанию: 22.
      Пароль вводится интерактивно.

  .\pc-report.ps1 -r user@host:2222
      То же с указанным SSH-портом.

  .\pc-report.ps1 -r pc_clients.txt
      Обработать список удалённых ПК.

  powershell.exe -ExecutionPolicy Bypass -File .\pc-report.ps1
  powershell.exe -ExecutionPolicy Bypass -File .\pc-report.ps1 -h
  powershell.exe -ExecutionPolicy Bypass -File .\pc-report.ps1 -r user@192.168.1.100

LISTFILE
  Текстовый файл, одна машина на строку:
    user ; ip/hostname ; password ; port

  user, ip/hostname и password обязательны.
  port необязателен; если пустой — 22.

  Пример:
    mike ; 192.168.1.100 ; secret123 ; 22
    admin ; pc-linux ; secret456 ;
    root ; server01 ; secret789 ; 2222

REMOTE-РЕЖИМ
  1. Устанавливается SSH-соединение.
  2. Определяется ОС удалённой машины.
  3. Для Windows передаётся и выполняется pc-report.ps1.
  4. Для Linux передаётся и выполняется pc-report.sh.
  5. HTML возвращается на запускающий ПК.
  6. На удалённом ПК HTML-файл не сохраняется.
  7. Отчёт сохраняется рядом с этим скриптом:
       PC_Report_<hostname>_<дата-время>_<уникальный суффикс>.html

  Оба сборщика встроены. Соседние файлы не требуются, в том числе для EXE.
  Удалённый сбор не меняет постоянную ExecutionPolicy.
  Неизвестный SSH-ключ подтверждается явно при интерактивном подключении.

ПАРАМЕТРЫ
  -h, -help
      Показать справку.

  -r, -remote <user@host[:port] | ListFile>
      Включить SSH remote-режим.

ПОДПИСЬ POWERSHELL (встроенный Signer)
  -Init                    инициализировать Signer: найти/создать сертификат и при
                           необходимости настроить ExecutionPolicy.
  -NewCert                 принудительно создать новый Code Signing сертификат.
  -SetPolicy               применить ExecutionPolicy для текущего пользователя.
  -PolicyAllSigned         установить AllSigned (имеет приоритет над -ExecutionPolicy).
  -f, -file, -folder, -path <файл|папка>
                           подписать файл или папку; для папки .ps1 рекурсивно по умолчанию.
  -VerifyOnly              только проверить подпись, ничего не подписывать.
  -NoRecurse               для папки не заходить в подпапки.
  -Unblock                 снять Mark-of-the-Web перед подписью.
  -NoTrust                 не добавлять сертификат в Root/TrustedPublisher.
  -CertName <имя>          имя сертификата Code Signing.
  -Years <1..30>           срок нового сертификата.
  -ExecutionPolicy <...>   RemoteSigned/AllSigned/Bypass/Restricted.

  ПРИМЕРЫ ИНИЦИАЛИЗАЦИИ
    .\pc-report.ps1 -Init
    .\pc-report.ps1 -Init -SetPolicy
    .\pc-report.ps1 -Init -SetPolicy -PolicyAllSigned
    .\pc-report.ps1 -Init -NewCert
    .\pc-report.ps1 -Init -NewCert -CertName "Long Lived Code Signing" -Years 30
    .\pc-report.ps1 -Init -NewCert -SetPolicy -PolicyAllSigned
    .\pc-report.ps1 -Init -NewCert -CertName "My Code Signing" -Years 10 -NoTrust

  ПРИМЕРЫ НАСТРОЙКИ ПОЛИТИКИ
    .\pc-report.ps1 -SetPolicy -ExecutionPolicy RemoteSigned
    .\pc-report.ps1 -SetPolicy -ExecutionPolicy AllSigned
    .\pc-report.ps1 -SetPolicy -PolicyAllSigned
    .\pc-report.ps1 -SetPolicy -ExecutionPolicy Bypass
    .\pc-report.ps1 -SetPolicy -ExecutionPolicy Restricted

  ПРИМЕРЫ ПОДПИСИ ФАЙЛОВ
    .\pc-report.ps1 -f "C:\project\1\myscript.ps1"
    .\pc-report.ps1 -file "C:\project\1\myscript.ps1"
    .\pc-report.ps1 -path "C:\project\1\module.psm1"
    .\pc-report.ps1 -f "C:\project\1\manifest.psd1"
    .\pc-report.ps1 -f "C:\project\1\myscript.ps1" -Unblock
    .\pc-report.ps1 -f "C:\project\1\myscript.ps1" -NoTrust
    .\pc-report.ps1 -f "C:\project\1\myscript.ps1" -CertName "My Code Signing"

  ПРИМЕРЫ ПОДПИСИ ПАПОК
    .\pc-report.ps1 -f "C:\project\1"
    .\pc-report.ps1 -folder "C:\project\1"
    .\pc-report.ps1 -f "C:\project\1" -NoRecurse
    .\pc-report.ps1 -f "C:\project\1" -Unblock
    .\pc-report.ps1 -f "C:\project\1" -CertName "My Code Signing"

  ПРИМЕРЫ ПРОВЕРКИ
    .\pc-report.ps1 -f "C:\project\1\myscript.ps1" -VerifyOnly
    .\pc-report.ps1 -f "C:\project\1" -VerifyOnly
    .\pc-report.ps1 -f "C:\project\1" -VerifyOnly -NoRecurse

  ТИПОВЫЕ ПОЛНЫЕ СЦЕНАРИИ
    # Создать сертификат на 30 лет, добавить доверие и включить AllSigned:
    .\pc-report.ps1 -Init -NewCert -CertName "Long Lived Code Signing" -Years 30 -SetPolicy -PolicyAllSigned

    # Подписать один скрипт после настройки AllSigned:
    .\pc-report.ps1 -f "C:\project\1\myscript.ps1"

    # Подписать весь проект вместе с вложенными папками:
    .\pc-report.ps1 -f "C:\project\1"

    # Подписать только файлы в корне проекта:
    .\pc-report.ps1 -f "C:\project\1" -NoRecurse

    # Снять блокировку Mark-of-the-Web и сразу подписать проект:
    .\pc-report.ps1 -f "C:\project\1" -Unblock

    # Проверить, что файлы проекта подписаны корректно:
    .\pc-report.ps1 -f "C:\project\1" -VerifyOnly

  АЛИАСЫ -f / -file / -folder / -path равнозначны для Target.
  Для одиночного файла поддерживаются .ps1, .psm1 и .psd1; при обработке
  папки выбираются .ps1. По умолчанию подпапки обрабатываются рекурсивно.

ЛОКАЛЬНЫЙ ОТЧЁТ СОБИРАЕТ
  ОС, CPU, motherboard/BIOS, все RAM-модули, GPU, логические и
  физические диски, сетевые интерфейсы, пользователей и сводку.

REMOTE АВТОРИЗАЦИЯ
  Для одиночного хоста используется системный ssh.exe с интерактивным
  вводом пароля.
  Для ListFile и PC_PASS используется OpenSSH SSH_ASKPASS_REQUIRE=force.
  Нужен OpenSSH с поддержкой askpass (8.4+); ключ хоста должен быть заранее
  подтверждён интерактивным подключением. Пароль не записывается в файл.
  Временный askpass.exe содержит только чтение окружения и удаляется.
  Без PC_PASS работают интерактивный пароль и SSH-ключи.

ТРЕБОВАНИЯ
  Windows PowerShell 5.1+
  OpenSSH Client (ssh.exe) для SSH.
  Для EXE не используйте PS2EXE -noConsole: нужны сообщения и запросы SSH.
  Сборка EXE не подписывает сам EXE и не требует соседних исходников.

РЕЗУЛЬТАТ
  Локально:
    PC_Report_<hostname>_<дата-время>_<уникальный суффикс>.html
  Remote:
    PC_Report_<hostname>_<дата-время>_<уникальный суффикс>.html

ПРИМЕРЫ
  .\pc-report.ps1
  .\pc-report.ps1 -h
  .\pc-report.ps1 -r mike@192.168.1.100
  .\pc-report.ps1 -r mike@192.168.1.100:22
  .\pc-report.ps1 -r pc_clients.txt
  powershell.exe -ExecutionPolicy Bypass -File .\pc-report.ps1 -r pc_clients.txt
'@ | Write-Host
}


function Show-SignerHelp {
@'
PS1 Signer — встроенная подпись .ps1/.psm1/.psd1 самоподписным сертификатом

Инициализация:
  .\pc-report.ps1 -Init
  .\pc-report.ps1 -Init -SetPolicy
  .\pc-report.ps1 -Init -SetPolicy -PolicyAllSigned
  .\pc-report.ps1 -Init -NewCert -CertName "Long Lived Code Signing" -Years 30

Подпись:
  .\pc-report.ps1 -f "C:\project\1\myscript.ps1"
  .\pc-report.ps1 -f "C:\project\1\"                 # папка + подпапки
  .\pc-report.ps1 -f "C:\project\1\" -NoRecurse     # только корень

Проверка:
  .\pc-report.ps1 -f "C:\project\1\myscript.ps1" -VerifyOnly

Дополнительно:
  -CertName <имя>       имя сертификата
  -Years <1..30>        срок действия
  -NewCert              создать новый сертификат принудительно
  -NoRecurse            не заходить в подпапки
  -Unblock              снять Mark-of-the-Web перед подписью
  -NoTrust              не добавлять сертификат в Root/TrustedPublisher
  -SetPolicy            изменить ExecutionPolicy текущего пользователя
  -PolicyAllSigned      установить AllSigned (имеет приоритет)
  -ExecutionPolicy ...  RemoteSigned / AllSigned / Bypass / Restricted
  -VerifyOnly           только проверка подписи

Пример требуемой настройки:
  .\pc-report.ps1 -Init -NewCert -CertName "Long Lived Code Signing" -Years 30 -SetPolicy -PolicyAllSigned

После AllSigned запуск неподписанных PowerShell-скриптов текущим пользователем
будет блокироваться. Сам сертификат хранится в CurrentUser\My; публичная
часть добавляется в CurrentUser\Root и CurrentUser\TrustedPublisher.
'@ | Write-Host
}

function Get-CodeSigningCertificates {
    $codeSigningOid = '1.3.6.1.5.5.7.3.3'
    @(
        Get-ChildItem Cert:\CurrentUser\My -ErrorAction SilentlyContinue | Where-Object {
            $_.HasPrivateKey -and $_.NotBefore -le (Get-Date) -and $_.NotAfter -gt (Get-Date) -and
            $_.EnhancedKeyUsageList -and (@($_.EnhancedKeyUsageList).ObjectId -contains $codeSigningOid)
        }
    )
}

function Find-SignerCertificate([string]$Name) {
    $subject = if ($Name -match '^CN=') { $Name } else { "CN=$Name" }
    $all = @(Get-CodeSigningCertificates)
    if ($all.Count -eq 0) { return $null }
    $exact = @($all | Where-Object { $_.FriendlyName -eq $Name -or $_.Subject -eq $subject })
    if ($exact.Count -gt 0) { return ($exact | Sort-Object NotAfter -Descending | Select-Object -First 1) }
    return $null
}

function Install-CertificateTrust([System.Security.Cryptography.X509Certificates.X509Certificate2]$Cert) {
    try {
        $publicBytes = $Cert.Export([System.Security.Cryptography.X509Certificates.X509ContentType]::Cert)
        $publicCert = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2($publicBytes)
        foreach ($storeName in @([System.Security.Cryptography.X509Certificates.StoreName]::Root,
                                  [System.Security.Cryptography.X509Certificates.StoreName]::TrustedPublisher)) {
            $store = New-Object System.Security.Cryptography.X509Certificates.X509Store($storeName,
                [System.Security.Cryptography.X509Certificates.StoreLocation]::CurrentUser)
            try { $store.Open([System.Security.Cryptography.X509Certificates.OpenFlags]::ReadWrite); $store.Add($publicCert) }
            finally { if ($store) { $store.Close() } }
        }
        Write-Host 'Сертификат добавлен в доверенные хранилища текущего пользователя.' -ForegroundColor Green
        return $true
    } catch {
        Write-Warning ("Не удалось добавить сертификат в доверенные хранилища: {0}" -f $_.Exception.Message)
        return $false
    }
}

function New-SelfSignedCodeSigningCert([string]$Name,[int]$ValidYears) {
    Import-Module PKI -ErrorAction SilentlyContinue
    if (-not (Get-Command New-SelfSignedCertificate -ErrorAction SilentlyContinue)) {
        throw 'New-SelfSignedCertificate недоступна. Нужна Windows 10/11 с модулем PKI.'
    }
    $subject = if ($Name -match '^CN=') { $Name } else { "CN=$Name" }
    $friendly = $Name -replace '^CN=', ''
    $created = New-SelfSignedCertificate -Subject $subject -FriendlyName $friendly -Type CodeSigningCert `
        -CertStoreLocation Cert:\CurrentUser\My -NotAfter (Get-Date).AddYears($ValidYears) `
        -KeyAlgorithm RSA -KeyLength 2048 -HashAlgorithm SHA256
    $cert = Get-ChildItem "Cert:\CurrentUser\My\$($created.Thumbprint)" -ErrorAction Stop
    Write-Host ("Сертификат создан. Thumbprint: {0}" -f $cert.Thumbprint) -ForegroundColor Green
    return $cert
}

function Set-ExecutionPolicySafe([string]$Policy) {
    try {
        Set-ExecutionPolicy -ExecutionPolicy $Policy -Scope CurrentUser -Force -ErrorAction Stop
        Write-Host ("ExecutionPolicy для текущего пользователя: {0}" -f $Policy) -ForegroundColor Green
        foreach ($scope in @('MachinePolicy','UserPolicy')) {
            $enforced=(Get-ExecutionPolicy -Scope $scope).ToString()
            if ($enforced -ne 'Undefined' -and $enforced -ne $Policy) { Write-Warning 'Групповая политика имеет приоритет; требуемый режим не действует.'; return $false }
        }
        if ((Get-ExecutionPolicy).ToString() -ne $Policy) { Write-Warning 'Действующая политика отличается из-за более приоритетной настройки; постоянная настройка текущего пользователя сохранена.' }
        return $true
    } catch {
        Write-Warning ("Не удалось изменить ExecutionPolicy: {0}" -f $_.Exception.Message)
        return $false
    }
}

function Test-ExecutionPolicyStatus {
    try {
        $currentUser=(Get-ExecutionPolicy -Scope CurrentUser).ToString(); $effective=(Get-ExecutionPolicy).ToString()
        Write-Host ("ExecutionPolicy: CurrentUser={0}, Effective={1}" -f $currentUser,$effective) -ForegroundColor Cyan
        if ($effective -eq 'Restricted') { Write-Warning 'Текущая политика Restricted может мешать запуску скриптов. Рекомендую -Init -SetPolicy.' }
    } catch { Write-Warning 'Не удалось прочитать действующую политику выполнения.' }
}

function Get-ScriptFiles([string]$Path,[switch]$TopLevelOnly) {
    if (-not (Test-Path -LiteralPath $Path)) { throw "Путь не найден: $Path" }
    $item=Get-Item -LiteralPath $Path -Force
    if ($item.PSIsContainer) {
        $params=@{LiteralPath=$Path;Filter='*.ps1';File=$true}
        if (-not $TopLevelOnly) {$params.Recurse=$true}
        return @(Get-ChildItem @params | Sort-Object FullName)
    }
    return @($item)
}

function Invoke-SignFile([string]$File,[System.Security.Cryptography.X509Certificates.X509Certificate2]$Cert,[switch]$UnblockFile) {
    $name=[IO.Path]::GetFileName($File)
    $ext=[IO.Path]::GetExtension($File).ToLowerInvariant()
    if ($ext -notin @('.ps1','.psm1','.psd1')) { Write-Warning ("Файл ""{0}"" не является .ps1/.psm1/.psd1." -f $name); return $false }
    $ro=$false
    try {
        $item=Get-Item -LiteralPath $File -Force; $ro=$item.IsReadOnly
        if ($ro) { Set-ItemProperty -LiteralPath $File -Name IsReadOnly -Value $false }
        if ($UnblockFile) { Unblock-File -LiteralPath $File -ErrorAction Stop }
        $null=Set-AuthenticodeSignature -FilePath $File -Certificate $Cert -HashAlgorithm SHA256 -Force -ErrorAction Stop
        $sig=Get-AuthenticodeSignature -FilePath $File
        if ($sig.Status -eq 'Valid') { Write-Host ("Скрипт ""{0}"" подписан." -f $name) -ForegroundColor Green; return $true }
        Write-Warning ("Скрипт ""{0}"": статус подписи {1}." -f $name,$sig.Status); return $false
    } catch { Write-Warning ("Ошибка подписи ""{0}"": {1}" -f $name,$_.Exception.Message); return $false }
    finally { if ($ro) { try { Set-ItemProperty -LiteralPath $File -Name IsReadOnly -Value $true } catch { Write-Warning "Не удалось восстановить атрибут 'только чтение' файла $name." } } }
}

function Invoke-VerifyFile([string]$File,[System.Security.Cryptography.X509Certificates.X509Certificate2]$Cert) {
    $name=[IO.Path]::GetFileName($File)
    try { $sig=Get-AuthenticodeSignature -FilePath $File -ErrorAction Stop
        if ($sig.Status -eq 'Valid' -and $sig.SignerCertificate.Thumbprint -eq $Cert.Thumbprint) { Write-Host ("Скрипт ""{0}"" подписан выбранным сертификатом." -f $name) -ForegroundColor Green; return $true }
        if ($sig.Status -eq 'Valid') { Write-Warning "Файл $name подписан другим сертификатом."; return $false }
        Write-Warning ("Скрипт ""{0}"": статус подписи {1}." -f $name,$sig.Status); return $false
    } catch { Write-Warning ("Ошибка проверки ""{0}"": {1}" -f $name,$_.Exception.Message); return $false }
}

function Invoke-SignerMode {
    if ($PolicyAllSigned) { $ExecutionPolicy='AllSigned' }
    if ([string]::IsNullOrWhiteSpace($CertName)) { $CertName='Local PowerShell Code Signing' }
    if ($SignerHelp) { Show-SignerHelp; return 0 }
    if ([string]::IsNullOrWhiteSpace($Target) -and -not $Init -and -not $NewCert -and -not $SetPolicy -and -not $PolicyAllSigned) { Show-SignerHelp; return 2 }

    $cert=$null
    if ($Init -or $NewCert) {
        if ($NewCert) { $cert=New-SelfSignedCodeSigningCert $CertName $Years }
        else { $cert=Find-SignerCertificate $CertName; if ($cert) { Write-Host ("Использую существующий сертификат: {0}" -f $cert.Thumbprint) -ForegroundColor Green } else { $cert=New-SelfSignedCodeSigningCert $CertName $Years } }
        if (-not $NoTrust -and $cert -and -not (Install-CertificateTrust $cert)) { return 1 }
        Test-ExecutionPolicyStatus
    }
    if ($SetPolicy -or $PolicyAllSigned) { if (-not (Set-ExecutionPolicySafe $ExecutionPolicy)) { return 1 }; Test-ExecutionPolicyStatus }
    if ([string]::IsNullOrWhiteSpace($Target)) { Write-Host 'Первоначальная настройка завершена.' -ForegroundColor Green; return 0 }

    if (-not $cert) { $cert=Find-SignerCertificate $CertName }
    if (-not $cert) { Write-Warning 'Указанный сертификат не найден. Сначала выполните -Init с тем же CertName.'; return 1 }
    if (-not $VerifyOnly -and -not $NoTrust -and -not (Install-CertificateTrust $cert)) { return 1 }
    $files=@(Get-ScriptFiles $Target -TopLevelOnly:$NoRecurse)
    if ($files.Count -eq 0) { Write-Warning 'Не найдены .ps1 файлы.'; return 1 }
    $total=0;$ok=0
    foreach($file in $files){$total++;if($VerifyOnly){if(Invoke-VerifyFile $file.FullName $cert){$ok++}}else{if(Invoke-SignFile $file.FullName $cert -UnblockFile:$Unblock){$ok++}}}
    if($VerifyOnly){$msg='Проверено: валидно'}else{$msg='Готово: подписано'}; Write-Host ("$msg $ok из $total.") -ForegroundColor Cyan
    return $(if($ok -eq $total -and $total -gt 0){0}else{1})
}

function Get-RemoteSpec([string]$Spec) {
    if ($Spec -notmatch '^([^@\s]+)@([^:\s]+)(?::(\d+))?$') {
        throw "Неверный адрес '$Spec'. Используйте user@host или user@host:port."
    }
    [pscustomobject]@{ User=$Matches[1]; Host=$Matches[2]; Port=if($Matches[3]){[int]$Matches[3]}else{22} }
}

function Find-CommandPath([string]$Name) {
    $c = Get-Command $Name -ErrorAction SilentlyContinue
    if ($c) { return $c.Source }
    return $null
}

function Read-RemotePassword([string]$Prompt) {
    $secure = Read-Host -Prompt $Prompt -AsSecureString
    $ptr=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure)
    try { return [Runtime.InteropServices.Marshal]::PtrToStringBSTR($ptr) }
    finally { [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($ptr) }
}

function Quote-Argument([string]$Value) {
    '"' + [regex]::Replace([regex]::Replace($Value,'(\\*)"','$1$1\"'),'(\\+)$','$1$1') + '"'
}
function Test-RemoteAddress([string]$User,[string]$RemoteHost,[int]$Port) {
    if ($User -cnotmatch '\A[A-Za-z0-9_А-Яа-яЁё][A-Za-z0-9_.А-Яа-яЁё-]*\z' -or $RemoteHost -notmatch '^[A-Za-z0-9_][A-Za-z0-9_.-]*$' -or $Port -lt 1 -or $Port -gt 65535) { throw 'Некорректные имя пользователя, адрес или порт (1..65535).' }
}
function Test-SSHAskpassSupport([string]$Executable) {
    $probe=New-Object Diagnostics.Process
    $probe.StartInfo=New-Object Diagnostics.ProcessStartInfo
    $probe.StartInfo.FileName=$Executable; $probe.StartInfo.Arguments='-V'
    $probe.StartInfo.UseShellExecute=$false
    $probe.StartInfo.RedirectStandardOutput=$true; $probe.StartInfo.RedirectStandardError=$true
    $started=$false
    try {
        [void]$probe.Start(); $started=$true
        $stdout=$probe.StandardOutput.ReadToEndAsync(); $stderr=$probe.StandardError.ReadToEndAsync()
        if (-not $probe.WaitForExit(15000)) { return $false }
        $version=$stdout.GetAwaiter().GetResult()+$stderr.GetAwaiter().GetResult()
        if ($version -notmatch 'OpenSSH_(?:for_Windows_)?(\d+)\.(\d+)') { return $false }
        return ([int]$Matches[1] -gt 8 -or ([int]$Matches[1] -eq 8 -and [int]$Matches[2] -ge 4))
    } catch { return $false }
    finally { if ($started -and -not $probe.HasExited) { $probe.Kill(); $probe.WaitForExit() }; $probe.Dispose() }
}
function Invoke-SSH([string]$User,[string]$RemoteHost,[int]$Port,[string]$Command,[byte[]]$InputBytes,[string]$Password,[double]$TimeoutSeconds=180) {
    Test-RemoteAddress $User $RemoteHost $Port
    $ssh=Find-CommandPath 'ssh.exe'
    if (-not $ssh) { throw 'Удалённый режим недоступен: SSH-клиент отсутствует. Ничего не устанавливается; локальный отчёт доступен.' }
    $p=New-Object Diagnostics.Process
    $p.StartInfo=New-Object Diagnostics.ProcessStartInfo
    $p.StartInfo.FileName=$ssh
    $p.StartInfo.UseShellExecute=$false
    $p.StartInfo.RedirectStandardInput=$true
    $p.StartInfo.RedirectStandardOutput=$true
    $p.StartInfo.RedirectStandardError=$true
    $p.StartInfo.StandardOutputEncoding=[Text.Encoding]::UTF8
    $p.StartInfo.StandardErrorEncoding=[Text.Encoding]::UTF8
    $options=@('-T','-o','ConnectTimeout=15','-o','ServerAliveInterval=10','-o','ServerAliveCountMax=3','-p',"$Port")
    $helperDir=$null; $started=$false
    try {
        if (-not [string]::IsNullOrEmpty($Password)) {
            if (-not (Test-SSHAskpassSupport $ssh)) { throw 'Автоматический пароль недоступен для этого SSH (нет поддержки askpass 8.4+). Ничего не устанавливается; доступны SSH-ключи и интерактивный запуск.' }
            # Askpass содержит только чтение окружения, никогда сам пароль.
            # Автоматический пароль разрешён только для уже доверенного ключа хоста.
            $helperDir=Join-Path ([IO.Path]::GetTempPath()) ([Guid]::NewGuid().ToString('N'))
            [void][IO.Directory]::CreateDirectory($helperDir)
            $helper=Join-Path $helperDir 'askpass.exe'
            $typeName='AskPass'+[Guid]::NewGuid().ToString('N')
            $source="using System; public class $typeName { public static void Main(string[] args) { Console.WriteLine(Environment.GetEnvironmentVariable(`"PC_REPORT_PASSWORD`")); } }"
            Add-Type -TypeDefinition $source -OutputAssembly $helper -OutputType ConsoleApplication -ErrorAction Stop
            $p.StartInfo.EnvironmentVariables['SSH_ASKPASS']=$helper
            $p.StartInfo.EnvironmentVariables['SSH_ASKPASS_REQUIRE']='force'
            $p.StartInfo.EnvironmentVariables['DISPLAY']='pc-report'
            $p.StartInfo.EnvironmentVariables['PC_REPORT_PASSWORD']=$Password
            $options+=@('-o','StrictHostKeyChecking=yes','-o','NumberOfPasswordPrompts=1')
        } else { $options+=@('-o','StrictHostKeyChecking=ask') }
        $options+=@("$User@$RemoteHost",$Command)
        $p.StartInfo.Arguments=($options | ForEach-Object { Quote-Argument $_ }) -join ' '
        Write-Log "Подключение: $User@$RemoteHost`:$Port"
        $clock=[Diagnostics.Stopwatch]::StartNew()
        [void]$p.Start(); $started=$true
        $out=New-Object Text.StringBuilder
        $stdout=$p.StandardOutput.ReadLineAsync(); $stderr=$p.StandardError.ReadLineAsync()
        $inputTask=$null
        if ($InputBytes -and $InputBytes.Length) { $inputTask=$p.StandardInput.BaseStream.WriteAsync($InputBytes,0,$InputBytes.Length) }
        else { $p.StandardInput.Close() }
        while ($stdout -or $stderr -or -not $p.HasExited) {
            if ($clock.Elapsed.TotalSeconds -ge $TimeoutSeconds) { throw ('Превышено время подключения/сбора ({0} секунд).' -f $TimeoutSeconds) }
            if ($inputTask -and $inputTask.IsCompleted) { $inputTask.GetAwaiter().GetResult(); $p.StandardInput.Close(); $inputTask=$null }
            if ($stdout -and $stdout.IsCompleted) {
                $line=$stdout.GetAwaiter().GetResult()
                if ($null -eq $line) { $stdout=$null } else { [void]$out.AppendLine($line); $stdout=$p.StandardOutput.ReadLineAsync() }
                if ($out.Length -gt 16777216) { throw 'Ответ превышает допустимый размер 16 МБ.' }
            }
            if ($stderr -and $stderr.IsCompleted) {
                $line=$stderr.GetAwaiter().GetResult()
                if ($null -eq $line) { $stderr=$null } else {
                    if ($Password) { $line=$line.Replace($Password,'[пароль скрыт]') }
                    Write-Log $line; $stderr=$p.StandardError.ReadLineAsync()
                }
            }
            Start-Sleep -Milliseconds 20
        }
        $p.WaitForExit()
        if ($p.ExitCode -ne 0) { throw "Подключение/сбор завершились с кодом $($p.ExitCode). См. сообщения выше." }
        return [pscustomobject]@{Out=$out.ToString();Err=''}
    } finally {
        if ($started -and -not $p.HasExited) { $p.Kill(); [void]$p.WaitForExit(3000) }
        $p.Dispose()
        [Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
        if ($helperDir -and [IO.Directory]::Exists($helperDir)) { [IO.Directory]::Delete($helperDir,$true) }
    }
}

function Detect-RemoteOS([string]$User,[string]$RemoteHost,[int]$Port,[string]$Password) {
    Test-RemoteAddress $User $RemoteHost $Port
    try {
        $r=Invoke-SSH $User $RemoteHost $Port 'powershell.exe -NoProfile -NonInteractive -Command "[Environment]::OSVersion.Platform"' $null $Password
        if ($r.Out -match 'Win32NT') { return 'Windows' }
    } catch { Write-Log 'Проверка Windows не удалась; пробую Linux.' }
    $r=Invoke-SSH $User $RemoteHost $Port 'uname -s' $null $Password
    if ($r.Out.Trim() -eq 'Linux') { return 'Linux' }
    throw 'Не удалось определить ОС удалённого хоста.'
}

function Get-WindowsCollectorCommand([int]$Length) {
    # Читаем ровно заданное число ASCII-байт, а не EOF Windows OpenSSH.
    $command='powershell.exe -NoLogo -NoProfile -NonInteractive -ExecutionPolicy Bypass -Command "$ErrorActionPreference=''Stop''; [Console]::OutputEncoding=[Text.UTF8Encoding]::new($false); $env:PSModulePath=[IO.Path]::Combine($PSHOME,''Modules''); [Console]::Error.WriteLine(''Windows collector: receiving data''); $b=New-Object byte[] __LENGTH__; $s=[Console]::OpenStandardInput(); $p=0; while ($p -lt $b.Length) { $n=$s.Read($b,$p,$b.Length-$p); if ($n -le 0) { throw ''Incomplete Windows collector transfer.'' }; $p+=$n }; [Console]::Error.WriteLine(''Windows collector: starting collection''); & ([scriptblock]::Create([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String([Text.Encoding]::ASCII.GetString($b)))))"'
    return $command.Replace('__LENGTH__',$Length.ToString([Globalization.CultureInfo]::InvariantCulture))
}

function Invoke-RemoteReport([string]$User,[string]$RemoteHost,[int]$Port,[string]$Password) {
    $os=Detect-RemoteOS $User $RemoteHost $Port $Password
    Write-Host "  ОС удалённого ПК: $os" -ForegroundColor DarkCyan
    if ($os -eq 'Windows') {
        $bytes=[Text.Encoding]::ASCII.GetBytes($EmbeddedWindows)
        $cmd=Get-WindowsCollectorCommand $bytes.Length
    } else {
        $bytes=[Convert]::FromBase64String($EmbeddedLinux)
        $cmd='bash -s'
    }
    $r=Invoke-SSH $User $RemoteHost $Port $cmd $bytes $Password
    $lines=@($r.Out -split "`r?`n" | Where-Object { $_ -match '^PCREPORT1:[A-Za-z0-9+/=]+:[A-Za-z0-9+/=]+$' })
    if ($lines.Count -ne 1) { throw 'Удалённый сборщик не вернул единственный корректный ответ.' }
    $fields=$lines[0].Split(':')
    try { return [pscustomobject]@{Name=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($fields[1]));Bytes=[Convert]::FromBase64String($fields[2])} }
    catch { throw 'Повреждён ответ удалённого сборщика.' }
}

function Save-RemoteReport([string]$User,[string]$RemoteHost,[int]$Port,[string]$Password) {
    Write-Host "`n→ $User@$RemoteHost`:$Port" -ForegroundColor Cyan
    $report=Invoke-RemoteReport $User $RemoteHost $Port $Password
    Save-Report $report.Name $report.Bytes
}

if ($SignerHelp -or $Init -or $NewCert -or $SetPolicy -or $Target -or $PolicyAllSigned -or $VerifyOnly -or $Unblock -or $NoTrust -or $NoRecurse) {
    if ($r) { Write-Log 'Нельзя совмещать удалённый сбор и управление подписью в одной команде.'; exit 2 }
    Write-Log 'Начало операции подписи/настройки сертификата'
    try { exit (Invoke-SignerMode) } catch { Write-Warning ("Ошибка Signer: {0}" -f $_.Exception.Message); exit 1 }
}
if ($h) { Show-Help; exit 0 }
if ($r) {
    try {
        if (Test-Path -LiteralPath $r -PathType Leaf) {
            $ok=0; $failed=0; $number=0
            foreach ($line in [IO.File]::ReadAllLines((Get-Item -LiteralPath $r).FullName,[Text.Encoding]::UTF8)) {
                $number++
                if (-not $line.Trim() -or $line -match '^\s*#') { continue }
                try {
                    $fields=$line.Split(';')
                    if ($fields.Count -lt 3 -or $fields.Count -gt 4) { throw 'Требуются 3 или 4 столбца.' }
                    $userName=$fields[0].Trim(); $address=$fields[1].Trim(); $password=$fields[2].Trim(); $port=22
                    if (-not $password) { throw 'Пароль в списке не может быть пустым.' }
                    if ($fields.Count -eq 4 -and $fields[3].Trim()) {
                        if (-not [int]::TryParse($fields[3].Trim(),[ref]$port)) { throw 'Порт должен быть числом.' }
                    }
                    Test-RemoteAddress $userName $address $port
                    Save-RemoteReport $userName $address $port $password; $ok++
                } catch { $failed++; Write-Log "Строка ${number}: ошибка. $($_.Exception.Message)" }
                finally { $password=$null }
            }
            Write-Log "Итог: успешно $ok, ошибок $failed."
            if ($failed -gt 0 -or $ok -eq 0) { exit 1 }; exit 0
        }
        $spec=Get-RemoteSpec $r
        # Без PC_PASS пароль/ключ обслуживает OpenSSH интерактивно, без повторного запроса здесь.
        Save-RemoteReport $spec.User $spec.Host $spec.Port $env:PC_PASS
        exit 0
    } catch { Write-Log "Ошибка: $($_.Exception.Message)"; exit 1 }
}


function Safe([object]$Value, [string]$Fallback = 'Не определено') {
    if ($null -eq $Value) { return $Fallback }
    $s = [string]$Value
    if ([string]::IsNullOrWhiteSpace($s)) { return $Fallback }
    return $s.Trim()
}

function Html([object]$Value, [string]$Fallback = 'Не определено') {
    return [System.Net.WebUtility]::HtmlEncode((Safe $Value $Fallback))
}

function Num([object]$Value) {
    try { return [double]$Value } catch { return 0 }
}

function Format-GB([object]$Bytes,[switch]$AllowZero) {
    if ($null -eq $Bytes) { return 'Не определено' }
    $n = Num $Bytes
    if ($n -lt 0 -or ($n -eq 0 -and -not $AllowZero)) { return 'Не определено' }
    return ('{0:N1} ГБ' -f ($n / 1GB))
}

function Format-MHz([object]$MHz) {
    $n = Num $MHz
    if ($n -le 0) { return 'Не определено' }
    return ('{0:N0} МГц' -f $n)
}

function Get-CimSafe([string]$Class, [string]$Namespace='root/cimv2') {
    Write-Log "Сбор: $Class"
    try {
        $args=@{ClassName=$Class;Namespace=$Namespace;OperationTimeoutSec=20;ErrorAction='Stop'}
        Get-CimInstance @args
    } catch { Write-Log "Не удалось получить $Class; соответствующие сведения недоступны. $($_.Exception.Message)"; @() }
}

function Get-DomainUsers([string]$Domain) {
    Add-Type -AssemblyName System.DirectoryServices -ErrorAction Stop
    $root=$null; $directory=$null; $searcher=$null; $results=$null
    try {
        $root=New-Object System.DirectoryServices.DirectoryEntry -ArgumentList "LDAP://$env:COMPUTERNAME/RootDSE"
        $root.AuthenticationType='Secure, Signing, Sealing'
        $namingContext=[string]$root.Properties['defaultNamingContext'].Value
        if ([string]::IsNullOrWhiteSpace($namingContext)) { throw 'Не удалось определить каталог собственного домена.' }
        $directory=New-Object System.DirectoryServices.DirectoryEntry -ArgumentList "LDAP://$env:COMPUTERNAME/$namingContext"
        $directory.AuthenticationType='Secure, Signing, Sealing'
        $searcher=New-Object System.DirectoryServices.DirectorySearcher -ArgumentList $directory
        $searcher.Filter='(&(objectCategory=person)(objectClass=user))'
        $searcher.SearchScope='Subtree'
        $searcher.ReferralChasing='None'
        # Постраничный поиск не обрезает список лимитом в 1000 записей.
        $searcher.PageSize=500; $searcher.SizeLimit=0; $searcher.CacheResults=$false
        $searcher.ClientTimeout=[TimeSpan]::FromSeconds(20)
        $searcher.ServerTimeLimit=[TimeSpan]::FromSeconds(20)
        $searcher.ServerPageTimeLimit=[TimeSpan]::FromSeconds(20)
        [void]$searcher.PropertiesToLoad.AddRange([string[]]@('samaccountname','description','useraccountcontrol'))
        $results=$searcher.FindAll()
        foreach ($entry in $results) {
            $name=[string]$entry.Properties['samaccountname'][0]
            if ([string]::IsNullOrWhiteSpace($name)) { throw 'Не удалось прочитать имя пользователя домена.' }
            $flags=$null
            if ($entry.Properties['useraccountcontrol'].Count) { $flags=[int]$entry.Properties['useraccountcontrol'][0] }
            [pscustomobject]@{
                Name=$name; Domain=(Safe $Domain $namingContext)
                Description=($entry.Properties['description'] -join '; ')
                AccountType=$(if ($null -ne $flags) { $flags -band 0x3B00 } else { $null })
                Disabled=$(if ($null -ne $flags) { ($flags -band 2) -ne 0 } else { $null })
            }
        }
    } finally {
        if ($null -ne $results) { $results.Dispose() }
        if ($null -ne $searcher) { $searcher.Dispose() }
        if ($null -ne $directory) { $directory.Dispose() }
        if ($null -ne $root) { $root.Dispose() }
    }
}

function Get-WindowsUsers([object]$ComputerSystem) {
    $domainController=$ComputerSystem.DomainRole -in @(4,5)
    $title=if ($domainController) { 'Пользователи домена' } else { 'Пользователи ПК' }
    $scope=if ($domainController) { 'domain account(s)' } else { 'local account(s)' }
    $accounts=@(); $countText='Не определено'
    try {
        if ($domainController) {
            Write-Log 'Сбор: пользователи собственного домена (контроллер домена)'
            $accounts=@(Get-DomainUsers $ComputerSystem.Domain)
            $emptyText='Пользователи домена не найдены.'
        } else {
            Write-Log 'Сбор: Win32_UserAccount (локальные пользователи)'
            $accounts=@(Get-CimInstance -ClassName Win32_UserAccount -Namespace root/cimv2 -Filter 'LocalAccount=True' -OperationTimeoutSec 20 -ErrorAction Stop)
            $emptyText='Локальные пользователи не найдены.'
        }
        $countText=[string]$accounts.Count
        Write-Log ("Получено пользователей: {0}" -f $accounts.Count)
    } catch {
        # Не выдаём ошибку или оборванный список за отсутствие пользователей.
        $accounts=@(); $countText='Не определено'
        $emptyText=if ($domainController) { 'Список пользователей домена недоступен.' } else { 'Список локальных пользователей недоступен.' }
        $emptyText+=" $($_.Exception.Message)"
        Write-Log $emptyText
    }
    [pscustomobject]@{Accounts=$accounts;CountText=$countText;EmptyText=$emptyText;Title=$title;Scope=$scope}
}

function Memory-Type([object]$Module) {
    $types=@{20='DDR';21='DDR2';24='DDR3';26='DDR4';30='LPDDR4';34='DDR5';35='LPDDR5'}
    $type=[int]$Module.SMBIOSMemoryType
    if (-not $types.ContainsKey($type)) { $type=[int]$Module.MemoryType }
    if ($types.ContainsKey($type)) { return $types[$type] }
    return 'Не определено'
}

function Row([string]$Name, [object]$Value) {
    "<tr><th>$(Html $Name)</th><td>$(Html $Value)</td></tr>"
}

function Pill([string]$Text, [string]$Kind='blue') {
    "<span class=""pill $Kind"">$(Html $Text)</span>"
}

$os = Get-CimSafe Win32_OperatingSystem | Select-Object -First 1
$cs = Get-CimSafe Win32_ComputerSystem | Select-Object -First 1
$bios = Get-CimSafe Win32_BIOS | Select-Object -First 1
$board = Get-CimSafe Win32_BaseBoard | Select-Object -First 1
$processors = @(Get-CimSafe Win32_Processor)
$cpu = $processors | Select-Object -First 1
$ram = @(Get-CimSafe Win32_PhysicalMemory)
$gpu = @(Get-CimSafe Win32_VideoController)
$logical = @(Get-CimSafe Win32_LogicalDisk | Where-Object { $_.DriveType -eq 3 })
$physical = @(Get-CimSafe Win32_DiskDrive)
$userInfo = Get-WindowsUsers $cs
$users = @($userInfo.Accounts)
$adapters = @(Get-CimSafe Win32_NetworkAdapterConfiguration | Where-Object { $_.IPEnabled -eq $true })

$hostname = Safe $env:COMPUTERNAME
$currentUser = Safe ([Security.Principal.WindowsIdentity]::GetCurrent().Name)
$osName = Safe $os.Caption
$osVersion = Safe $os.Version
$osBuild = Safe $os.BuildNumber
$arch = Safe $os.OSArchitecture
$bits = if ($arch -match '64') { '64-битная' } elseif ($arch -match '32') { '32-битная' } else { 'Не определено' }
$uptime = if ($os.LastBootUpTime) {
    try {
        $boot = if ($os.LastBootUpTime -is [datetime]) { $os.LastBootUpTime } else { [Management.ManagementDateTimeConverter]::ToDateTime($os.LastBootUpTime) }
        $span = (Get-Date) - $boot
        '{0} дн. {1} ч. {2} мин.' -f [Math]::Floor($span.TotalDays), $span.Hours, $span.Minutes
    } catch { 'Не определено' }
} else { 'Не определено' }

$totalRam = ($ram | ForEach-Object { Num $_.Capacity } | Measure-Object -Sum).Sum
$ramFree = (Num $os.FreePhysicalMemory) * 1KB
$cpuCores = ($processors | Measure-Object -Property NumberOfCores -Sum).Sum
$cpuThreads = ($processors | Measure-Object -Property NumberOfLogicalProcessors -Sum).Sum
if (-not $os -or -not $cs) { Write-Log 'Основные сведения о системе недоступны; отчёт не создан.'; exit 1 }
if ($totalRam -le 0) { $totalRam=Num $cs.TotalPhysicalMemory }
$ramUsed=[Math]::Max([double]0,(Num $os.TotalVisibleMemorySize)*1KB-$ramFree)
$ramTotalText=if ($totalRam -gt 0) { '{0} ГБ' -f [Math]::Round($totalRam/1GB,1) } else { 'Не определено' }
$ramFreeText=if ($null -ne $os.FreePhysicalMemory) { '{0} ГБ' -f [Math]::Round($ramFree/1GB,1) } else { 'Не определено' }
$ramUsedText=if ($null -ne $os.FreePhysicalMemory -and $null -ne $os.TotalVisibleMemorySize) { '{0} ГБ' -f [Math]::Round($ramUsed/1GB,1) } else { 'Не определено' }
if (-not $processors.Count) { $cpuCores='Не определено'; $cpuThreads='Не определено' }

$ramRows = if ($ram.Count -gt 0) {
    for ($i=0; $i -lt $ram.Count; $i++) {
        $m = $ram[$i]
        $speed = if ((Num $m.ConfiguredClockSpeed) -gt 0) { $m.ConfiguredClockSpeed } else { $m.Speed }
        "<tr><td>#$($i+1)</td><td>$(Html $m.Manufacturer)</td><td>$(Html $m.PartNumber)</td><td>$(Html (Format-GB $m.Capacity))</td><td>$(Html (Memory-Type $m))</td><td>$(Html (Format-MHz $speed))</td><td>$(Html $m.SerialNumber)</td></tr>"
    }
} else { '<tr><td colspan="7">Модули памяти не определены.</td></tr>' }

$gpuCards = if ($gpu.Count -gt 0) {
    foreach ($g in $gpu) {
        # AdapterRAM — 32-битное поле, размер современных GPU здесь недостоверен.
        $vram = 'Не определено (CIM не даёт достоверный объём)'
        @"
<div class="card">
  <h3>$(Html $g.Name) <span class="tag">$(Html $vram)</span></h3>
  <table>
    $(Row 'Полное наименование' $g.Name)
    $(Row 'Производитель' $g.AdapterCompatibility)
    $(Row 'Видеопамять' $vram)
    $(Row 'Графический процессор' $g.VideoProcessor)
    $(Row 'Драйвер' $g.DriverVersion)
    $(Row 'Дата драйвера' $g.DriverDate)
    $(Row 'Разрешение' $(if ($g.CurrentHorizontalResolution -gt 0 -and $g.CurrentVerticalResolution -gt 0) { '{0}x{1}' -f $g.CurrentHorizontalResolution,$g.CurrentVerticalResolution } else { 'Не определено' }))
    $(Row 'Частота обновления' $(if ($g.CurrentRefreshRate -gt 0) { '{0} Гц' -f $g.CurrentRefreshRate } else { 'Не определено' }))
    $(Row 'Статус' $g.Status)
  </table>
</div>
"@
    }
} else { '<div class="card"><h3>Видеокарта</h3><p>Информация не определена.</p></div>' }

$diskCards = foreach ($d in $logical) {
    $total = Num $d.Size
    $free = Num $d.FreeSpace
    $used = [Math]::Max([double]0, $total - $free)
    $pct = if ($total -gt 0) { [Math]::Round(($used/$total)*100,0) } else { 0 }
    $kind = if ($pct -ge 90) { 'crit' } elseif ($pct -ge 75) { 'warn' } else { 'ok' }
    @"
<div class="card">
  <h3>$(Html $d.DeviceID) <span class="tag">$(Html $d.FileSystem)</span></h3>
  <table>
    $(Row 'Название тома' $d.VolumeName)
    $(Row 'Файловая система' $d.FileSystem)
    $(Row 'Общий объём' (Format-GB $total))
    $(Row 'Занято' ("{0} ({1}%)" -f (Format-GB $used -AllowZero),$pct))
    $(Row 'Свободно' (Format-GB $d.FreeSpace -AllowZero))
  </table>
  <div class="bar"><div class="$kind" style="width:${pct}%"></div></div>
</div>
"@
}

$physicalRows = foreach ($d in $physical) {
    "<tr><td>$(Html $d.Index)</td><td>$(Html $d.Model)</td><td>$(Html (Format-GB $d.Size))</td><td>$(Html $d.InterfaceType)</td><td>$(Html $d.SerialNumber)</td></tr>"
}

$netCards = foreach ($a in $adapters) {
    $dhcp = if ($a.DHCPEnabled) { 'DHCP' } else { 'STATIC' }
    $kind = if ($a.DHCPEnabled) { 'green' } else { 'amber' }
    $ipv4 = @($a.IPAddress | Where-Object { $_ -notmatch ':' }) -join ', '
    $ipv6 = @($a.IPAddress | Where-Object { $_ -match ':' }) -join ', '
    $mask = @($a.IPSubnet) -join ', '
    $gw = @($a.DefaultIPGateway) -join ', '
    $dns = @($a.DNSServerSearchOrder) -join ', '
    @"
<div class="card">
  <h3>$(Html $a.Description) $(Pill $dhcp $kind)</h3>
  <table>
    $(Row 'MAC-адрес' $a.MACAddress)
    $(Row 'IPv4' $ipv4)
    $(Row 'IPv6' $ipv6)
    $(Row 'Маска / префикс' $mask)
    $(Row 'Шлюз по умолчанию' $gw)
    $(Row 'DNS' $dns)
  </table>
</div>
"@
}

$userRows = foreach ($u in $users | Sort-Object Domain,Name) {
    "<tr><td>$(Html $u.Name)</td><td>$(Html $u.Domain)</td><td>$(Html $u.Description)</td><td>$(Html $u.AccountType)</td><td>$(Html $u.Disabled)</td></tr>"
}

if (-not $diskCards) { $diskCards='<div class="card"><h3>Диски</h3><p>Сведения не получены.</p></div>' }
if (-not $physicalRows) { $physicalRows='<tr><td colspan="5">Сведения не получены.</td></tr>' }
if (-not $netCards) { $netCards='<div class="card"><h3>Сеть</h3><p>Сведения не получены.</p></div>' }
if (-not $userRows) { $userRows="<tr><td colspan=""5"">$(Html $userInfo.EmptyText)</td></tr>" }

$cpuCards = foreach ($processor in $processors) {
    @"
<div class="card"><h3>$(Html $processor.Name) <span class="tag">$($processor.NumberOfCores) ядер / $($processor.NumberOfLogicalProcessors) потоков</span></h3><table>
$(Row 'Производитель' $processor.Manufacturer)
$(Row 'Физических процессоров' $processors.Count)
$(Row 'Физических ядер' $processor.NumberOfCores)
$(Row 'Логических процессоров' $processor.NumberOfLogicalProcessors)
$(Row 'Текущая частота' (Format-MHz $processor.CurrentClockSpeed))
$(Row 'Максимальная частота' (Format-MHz $processor.MaxClockSpeed))
$(Row 'Кэш L2' $(if($processor.L2CacheSize){"$($processor.L2CacheSize) КБ"}else{'Не определено'}))
$(Row 'Кэш L3' $(if($processor.L3CacheSize){"$($processor.L3CacheSize) КБ"}else{'Не определено'}))
$(Row 'Socket' $processor.SocketDesignation)
</table></div>
"@
}
if (-not $cpuCards) { $cpuCards='<div class="card"><h3>Процессор</h3><p>Не определено.</p></div>' }

$html = @"
<!DOCTYPE html>
<html lang="ru">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>PC Report - $(Html $hostname) - $($ReportDate.ToString('dd.MM.yyyy HH:mm'))</title>
<style>
:root{--bg:#0d1117;--panel:#161b22;--panel2:#1c2330;--border:#30363d;--text:#c9d1d9;--dim:#8b949e;--blue:#388bfd;--accent:#58a6ff;--green:#3fb950;--amber:#d29922;--red:#f85149;--mono:"JetBrains Mono","Cascadia Code","Fira Code",Consolas,"Courier New",monospace}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{background:var(--bg);color:var(--text);font-family:var(--mono);font-size:14px;line-height:1.55;padding-bottom:60px}
.wrap{max-width:1180px;margin:0 auto;padding:0 24px}
header.hero{background:linear-gradient(135deg,#0d1117 0%,#10243f 60%,#0f2f52 100%);border-bottom:2px solid var(--blue);padding:34px 0 26px}
h1{font-size:44px;letter-spacing:4px;color:#fff;text-transform:uppercase}
h1 .dot{color:var(--accent)}
.sub{display:flex;gap:26px;flex-wrap:wrap;margin-top:12px;color:var(--dim);font-size:13px}
.sub b{color:var(--accent);font-weight:600}
.badges{margin-top:14px;display:flex;gap:10px;flex-wrap:wrap}
.badge{background:#1f6feb22;border:1px solid var(--blue);color:var(--accent);padding:3px 12px;border-radius:20px;font-size:12px}
nav.toc{position:sticky;top:0;z-index:50;background:#0d1117ee;backdrop-filter:blur(6px);border-bottom:1px solid var(--border);padding:10px 0}
nav.toc .wrap{display:flex;gap:6px;flex-wrap:wrap}
nav.toc a{color:var(--dim);text-decoration:none;font-size:12px;padding:5px 12px;border-radius:6px;border:1px solid transparent}
nav.toc a:hover{color:var(--accent);border-color:var(--border);background:var(--panel)}
section{margin-top:34px;scroll-margin-top:58px}
.sec-title{display:flex;align-items:center;gap:12px;font-size:20px;color:#fff;letter-spacing:1px;margin-bottom:16px}
.sec-title .ico{width:34px;height:34px;display:flex;align-items:center;justify-content:center;background:var(--panel2);border:1px solid var(--border);border-radius:8px;font-size:17px}
.sec-title .num{color:var(--blue);font-size:14px}
.grid{display:grid;gap:16px}.g2{grid-template-columns:repeat(auto-fit,minmax(340px,1fr))}
.card{background:var(--panel);border:1px solid var(--border);border-radius:10px;padding:18px 20px;transition:border-color .2s,transform .2s}
.card:hover{border-color:var(--blue);transform:translateY(-2px)}
.card h3{font-size:15px;color:var(--accent);margin-bottom:12px;display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap}
.card h3 .tag{font-size:11px;color:var(--dim);font-weight:400}
table{width:100%;border-collapse:collapse;font-size:13px}
th,td{text-align:left;padding:7px 10px;border-bottom:1px solid var(--border);vertical-align:top;overflow-wrap:anywhere}
th{color:var(--dim);font-weight:500;width:38%;white-space:nowrap}
tr:last-child th,tr:last-child td{border-bottom:none}
.bar{height:10px;background:#21262d;border-radius:5px;overflow:hidden;margin-top:8px}
.bar>div{height:100%;border-radius:5px}
.bar .ok{background:linear-gradient(90deg,#238636,#3fb950)}.bar .warn{background:linear-gradient(90deg,#bb8009,#d29922)}.bar .crit{background:linear-gradient(90deg,#da3633,#f85149)}
.pill{display:inline-block;padding:2px 10px;border-radius:12px;font-size:11px;margin:2px 4px 2px 0}
.pill.green{background:#23863622;color:var(--green);border:1px solid #238636}.pill.blue{background:#1f6feb22;color:var(--accent);border:1px solid var(--blue)}.pill.gray{background:#21262d;color:var(--dim);border:1px solid var(--border)}.pill.amber{background:#9e6a0322;color:var(--amber);border:1px solid #9e6a03}
.big-num{font-size:26px;color:#fff;font-weight:700}.dim{color:var(--dim)}
pre.term{background:#010409;border:1px solid var(--border);border-radius:8px;padding:14px 16px;font-size:12px;overflow-x:auto;color:#7ee787}
pre.term .p{color:var(--accent)}
footer{margin-top:50px;border-top:1px solid var(--border);padding-top:18px;color:var(--dim);font-size:12px}
footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px}
@media(max-width:600px){.wrap{padding:0 12px}h1{font-size:30px}.g2{grid-template-columns:1fr}th{white-space:normal}}
@media print{body{background:#fff;color:#111}.hero{break-after:avoid}.card{border-color:#bbb;background:#fafafa}.toc{display:none}.card:hover{transform:none}}
</style>
</head>
<body>
<header class="hero"><div class="wrap">
<h1>PC<span class="dot">&bull;</span>REPORT</h1>
<div class="sub">
<span>КОМПЬЮТЕР: <b>$(Html $hostname)</b></span>
<span>ДАТА ОТЧЁТА: <b>$($ReportDate.ToString('dd.MM.yyyy HH:mm'))</b></span>
<span>ПОЛЬЗОВАТЕЛЬ: <b>$(Html $currentUser)</b></span>
</div>
<div class="badges">
<span class="badge">$(Html $osName)</span>
<span class="badge">$(Html $arch) · $(Html $bits)</span>
<span class="badge">$(Html $ramTotalText) RAM</span>
<span class="badge">$cpuCores ядер / $cpuThreads потоков</span>
<span class="badge">$($gpu.Count) GPU</span>
</div>
</div></header>

<nav class="toc"><div class="wrap">
<a href="#os">ОС</a><a href="#cpu">Процессор</a><a href="#mb">Плата</a><a href="#ram">Память</a>
<a href="#gpu">Видеокарта</a><a href="#disk">Диски</a><a href="#net">Сеть</a><a href="#users">Пользователи</a><a href="#summary">Сводка</a>
</div></nav>

<section id="os"><div class="wrap">
<div class="sec-title"><span class="ico">🖥</span><span class="num">01</span> Операционная система</div>
<div class="grid g2">
<div class="card"><h3>Система</h3><table>
$(Row 'Полное наименование' $osName)
$(Row 'Версия' "$osVersion (сборка $osBuild)")
$(Row 'Архитектура' $arch)
$(Row 'Разрядность' $bits)
</table></div>
<div class="card"><h3>Платформа</h3><table>
$(Row 'Изготовитель' $cs.Manufacturer)
$(Row 'Модель' $cs.Model)
$(Row 'Имя компьютера' $hostname)
$(Row 'Аптайм' $uptime)
$(Row 'Тип системы' $cs.SystemType)
</table></div>
</div></div></section>

<section id="cpu"><div class="wrap">
<div class="sec-title"><span class="ico">🧠</span><span class="num">02</span> Процессор</div>
<div class="grid g2">
$($cpuCards -join "`n")
</div></div></section>

<section id="mb"><div class="wrap">
<div class="sec-title"><span class="ico">🔲</span><span class="num">03</span> Материнская плата</div>
<div class="grid g2">
<div class="card"><h3>Плата</h3><table>
$(Row 'Полное наименование' "$($board.Manufacturer) $($board.Product)")
$(Row 'Производитель' $board.Manufacturer)
$(Row 'Модель' $board.Product)
$(Row 'Версия платы' $board.Version)
$(Row 'Серийный номер' $board.SerialNumber)
</table></div>
<div class="card"><h3>BIOS / UEFI</h3><table>
$(Row 'Производитель BIOS' $bios.Manufacturer)
$(Row 'Версия BIOS' $bios.SMBIOSBIOSVersion)
$(Row 'Дата BIOS' $bios.ReleaseDate)
$(Row 'SMBIOS' $bios.SMBIOSMajorVersion)
</table></div>
</div></div></section>

<section id="ram"><div class="wrap">
<div class="sec-title"><span class="ico">📊</span><span class="num">04</span> Оперативная память</div>
<div class="grid g2">
<div class="card"><h3>Итог</h3>
<div class="big-num">$(Html $ramTotalText)</div>
<div style="margin-top:10px;font-size:13px">
<div><span class="dim">Модулей установлено:</span> $($ram.Count)</div>
<div><span class="dim">Свободно сейчас:</span> $(Html $ramFreeText)</div>
<div><span class="dim">Занято сейчас:</span> $(Html $ramUsedText)</div>
</div></div>
<div class="card"><h3>Модули памяти</h3>
<table><tr><th>№</th><th>Производитель</th><th>Part Number</th><th>Объём</th><th>Тип</th><th>Частота</th><th>Serial</th></tr>
$($ramRows -join "`n")
</table></div>
</div></div></section>

<section id="gpu"><div class="wrap">
<div class="sec-title"><span class="ico">🎮</span><span class="num">05</span> Видеокарта</div>
<div class="grid g2">$($gpuCards -join "`n")</div>
</div></section>

<section id="disk"><div class="wrap">
<div class="sec-title"><span class="ico">💾</span><span class="num">06</span> Дисковое пространство</div>
<div class="grid g2">$($diskCards -join "`n")</div>
<div class="card" style="margin-top:16px"><h3>Физические диски</h3>
<table><tr><th>№</th><th>Модель</th><th>Объём</th><th>Интерфейс</th><th>Serial</th></tr>
$($physicalRows -join "`n")
</table></div>
</div></section>

<section id="net"><div class="wrap">
<div class="sec-title"><span class="ico">🌐</span><span class="num">07</span> Сетевые интерфейсы</div>
<div class="grid g2">$($netCards -join "`n")</div>
</div></section>

<section id="users"><div class="wrap">
<div class="sec-title"><span class="ico">👤</span><span class="num">08</span> Пользователи</div>
<div class="grid g2">
<div class="card"><h3>Текущая сессия</h3><table>
$(Row 'Запущено от имени' $currentUser)
$(Row 'Имя пользователя' $env:USERNAME)
$(Row 'Имя компьютера' $hostname)
</table></div>
<div class="card"><h3>$(Html $userInfo.Title) <span class="tag">всего: $(Html $userInfo.CountText)</span></h3>
<table><tr><th>Имя</th><th>Домен</th><th>Описание</th><th>Тип</th><th>Отключён</th></tr>
$($userRows -join "`n")
</table></div>
</div></div></section>

<section id="summary"><div class="wrap">
<div class="sec-title"><span class="ico">⌨️</span><span class="num">09</span> Сводка</div>
<pre class="term"><span class="p">&gt;</span> hostname      → $(Html $hostname)
<span class="p">&gt;</span> os            → $(Html $osName) · $(Html $osVersion) · $(Html $arch) $(Html $bits)
<span class="p">&gt;</span> cpu           → $(Html (($processors | ForEach-Object { $_.Name }) -join ' / ')) · $cpuCores cores / $cpuThreads threads
<span class="p">&gt;</span> motherboard   → $(Html "$($board.Manufacturer) $($board.Product)")
<span class="p">&gt;</span> ram           → $(Html $ramTotalText) · $($ram.Count) module(s)
<span class="p">&gt;</span> gpu           → $($gpu.Count) adapter(s)
<span class="p">&gt;</span> volumes       → $($logical.Count) logical volume(s)
<span class="p">&gt;</span> physical      → $($physical.Count) physical disk(s)
<span class="p">&gt;</span> network       → $($adapters.Count) configured interface(s)
<span class="p">&gt;</span> users         → $(Html $userInfo.CountText) $(Html $userInfo.Scope)
</pre></div></section>

<footer><div class="wrap">
<span>Отчёт сформирован pc-report.ps1 · $($ReportDate.ToString('dd.MM.yyyy HH:mm'))</span>
<span>Хост: $(Html $hostname) · Автономный HTML, без внешних ресурсов</span>
</div></footer>
</body>
</html>
"@

Write-Log 'Сбор завершён; отчёт сформирован.'
if ($RemoteExportBase64) {
    $bytes=[Text.Encoding]::UTF8.GetBytes($html)
    $name=[Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($hostname))
    [Console]::Out.WriteLine(('PCREPORT1:{0}:{1}' -f $name,[Convert]::ToBase64String($bytes)))
    exit 0
}
try { Save-Report $hostname ([Text.Encoding]::UTF8.GetBytes($html)) }
catch { Write-Log "Не удалось сохранить отчёт: $($_.Exception.Message)"; exit 1 }
